/* Right-hand case dossiers only. No coordinates, boundaries or layer controls.
 * Source keys resolve against the shared source register; each paragraph carries
 * its own citations. Interpretations and proposed tests are not reported findings.
 * Live attraction descriptions checked 13 October 2026 are not 2024 observations.
 */
const caseResearch = (() => {
  const record = (title, text, refs) => ({ title, text, refs, kind: 'record' });
  const reading = (title, text, refs = []) => ({ title, text, refs, kind: 'interpretation' });
  const gap = (text) => ({ title: 'What would substantiate this interpretation?', text, refs: [], kind: 'gap' });
  const dossier = (sections, related = []) => ({ sections, related });
  const profile = (sections, related = []) => ({ sections, related, featured: true });
  const newSources = {
    nparksStoneboat: ['Stoneboat and Tea Pavilion', 'chinese-garden/stoneboat-and-tea-pavilion/'],
    nparksSwamp: ['Alstonia Island & Freshwater Swamp Forest', 'lakeside-garden/alstonia-island/'],
    nparksRasau: ['Rasau Walk', 'lakeside-garden/rasau-walk/'],
    nparksForest: ['Forest Ramble (Nature Playgarden)', 'lakeside-garden/forest-ramble/'],
    nparksTherapeutic: ['Therapeutic Garden', 'lakeside-garden/therapeutic-garden/'],
    nparksClusia: ['Clusia Cove', 'lakeside-garden/clusia-cove/'],
    nparksNeram: ['Neram Streams', 'lakeside-garden/neram-streams/'],
    nparksAllotments: ['Allotment Gardens', 'lakeside-garden/allotment-gardens/'],
    nparksBonsai: ['Bonsai Garden', 'chinese-garden/bonsai-garden/'],
    nparksCreek: ['Cascading Creek', 'chinese-garden/cascading-creek/'],
    nparksLily: ['Water Lily Garden', 'japanese-garden/water-lily-garden/'],
    nparksSmart: ['Smart Technology', 'building-a-smart-sustainable-garden-district/smart-technology/'],
    nparksWaterSystems: ['Sustainability', 'building-a-smart-sustainable-garden-district/sustainability/']
  };
  const cases = {
    'jurong-lake': dossier([
      record('From a river to a managed freshwater landscape', 'The 2024 opening speech dates the completion of river-mouth sluice works to 1971 and links the resulting lake to the Japanese Garden in 1973 and Chinese Garden in 1975. This is a retrospective institutional account: it establishes a chronology, not the exact shoreline or gate position on a historical map.', ['pmoOpening']),
      record('Habitat does not sit outside infrastructure', 'The current Floating Wetlands page explicitly identifies PUB’s ABC Waters management and combines water-quality and wildlife-habitat purposes. The lake is therefore encountered through overlapping water-management and garden institutions, rather than through one autonomous park ecosystem.', ['nparksWetlands']),
      reading('Political ecology: several kinds of water value', 'Containing water makes a new set of landscape uses possible: scenic edges, habitat displays and cultural gardens. Our interpretation is that these uses redistribute the meaning of water from a river relationship toward a managed public resource. That does not mean the resulting ecology is unreal. The important distinction is between living ecological processes and the institutions that select, contain and maintain them.'),
      reading('Reading change without inventing a hydrological model', 'Compare the dated historical rasters for the appearance of channels, banks and garden islands. Their visual difference can support a cartographic change description, but not a measured inundation area without checking map scale, registration error and classification. Today’s URA waterbody polygon must not be treated as the 1971 lake footprint.', ['nus1963', 'nus1971', 'uraWaterGeo']),
      gap('Engineering drawings, dated aerial imagery, water-level records and sediment or biodiversity monitoring would be needed to quantify the change. A pleasant lake view alone cannot demonstrate improved water quality or ecosystem resilience.')
    ], ['water-engineering', 'floating-wetlands', 'jurong-river-trace']),
    'water-engineering': dossier([
      record('An engineering event, not a surveyed alignment', 'The official speech describes sluice-gate construction at the river mouth and completion in 1971. It does not publish a recoverable alignment. The previous hand-drawn line has consequently been removed; the evidence belongs in a source-only case, not in an apparently precise GIS feature.', ['pmoOpening']),
      record('Later systems need their own chronology', 'NParks’ current sustainability description includes rainwater collection, bioretention, irrigation reuse and a closed-loop system at Clusia Cove. These are different interventions from the original damming of Jurong River; they should not be collapsed into a single timeless “water engineering” layer.', ['nparksWaterSystems']),
      reading('Political ecology: make operating dependencies visible', 'For this case, the relevant relationships are control of water, responsibility for treatment, and the daily work that sustains a recreational waterscape. A credible network would connect inlets, treatment cells, pumps, outlets and the responsible operator. Attractive blue lines without engineering provenance would conceal precisely the institutional and material relationships the GIS should reveal.'),
      gap('Obtain as-built plans with coordinate reference systems and documented operating dates before drawing a historical network. The present account does not establish pumping energy, treatment volumes, costs or working conditions.')
    ], ['jurong-lake', 'living-lab-governance']),
    'lakeside-garden': dossier([
      record('A public landscape with an explicit design brief', 'NParks identifies the western section as 60 hectares and organises its purpose around nature, play and community. Its current description encourages walking, cycling and public transport within the district’s car-lite strategy. These are official purposes and promotional choices, not a survey of who actually visits.', ['nparksLakeside']),
      record('A useful measure with a limited denominator', 'The September 2024 speech reports 25 million visits since the 2019 opening and explicitly notes repeat visitation. This is evidence of substantial reported use, but it is not 25 million distinct people, an annual figure, or evidence of equitable access. The speech does not explain the counting method.', ['pmoOpening']),
      reading('Political ecology: publicness is assembled', 'A family visit is enabled by a chain of services: transport, entrances, usable paths, toilets, drinking water, shade and places to pause. Children’s play, care-oriented gardens and community venues make different publics visible. The landscape’s success should therefore be judged by which needs the network accommodates, rather than by area or visitor totals alone.'),
      reading('Promotion and achieved purpose are different evidence', 'Calling a garden welcoming expresses an institutional aspiration. Demonstrating it would require disaggregating experience by mobility, caregiving demands, work schedule and ability to pay for optional activities. A popular park can still contain uneven access; we do not assume either equality or exclusion without local evidence.'),
      gap('Use structured weekday/weekend observations, entrance counts with a published method, interviews and route audits. Do not infer demographic groups from photos or construct a usage heatmap from facility locations.')
    ], ['forest-ramble', 'therapeutic-garden', 'access-network']),
    'chinese-garden': dossier([
      record('A constructed cultural landscape on productive land', 'NHB describes fish and prawn ponds before the garden, construction beginning in 1971, and completion in April 1975. Its account locates the garden within JTC’s industrial-estate development, including a visitor-attraction purpose. The garden was thus deliberately made, not an untouched remnant.', ['nhbChinese']),
      record('What persisted through rejuvenation', 'NParks’ dated 2024 completion account distinguishes retained familiar landmarks from new additions. Grand Arch and the pagodas are part of the retained architectural ensemble, while new facilities change how that ensemble is encountered. Continuity of an icon is not continuity of every function or planting scheme.', ['nparks2024Opening']),
      reading('Authenticity: specify what is being evaluated', 'Architectural continuity, cultural interpretation and ecological self-reproduction are three different claims. A transplanted design can become meaningful local heritage through repeated use and memory. That does not make its original construction “natural”, nor does it validate every later claim about traditional culture. The map should allow these forms of authenticity to coexist rather than forcing a real/fake verdict.'),
      reading('Selective memory, not an accusation of total erasure', 'NHB already acknowledges the ponds. Our critical question is how much narrative space is given to productive livelihoods compared with monumental architecture. An online exhibition is not an inventory of the signs on site. We cannot assert that interpretive material hides a history until its wording, locations and languages have been systematically recorded.'),
      gap('Compare the 1975 opening document, dated photographs and present interpretive signs; interview long-term users about remembered activities. A sign audit could add pond livelihoods and changing garden functions without inventing operators or boundaries.')
    ], ['former-fish-ponds', 'lone-tree-memory']),
    'japanese-garden': dossier([
      record('Construction, planting and opening are different events', 'NHB records that work on Seiwaen Japanese Garden began in May 1968, that it officially opened in February 1973, and that Kinsaku Nakane designed the 32-acre garden on a man-made island. PMO independently dates completion to 1973. The current NParks page preserves a separate memory of cycads planted by Akihito and Michiko in 1970. Construction, ceremonial planting and public opening must therefore remain distinct dates.', ['nhbJapanese', 'pmoOpening', 'nparksJapanese']),
      record('The historical island is visible, but the GIS point is not its boundary', 'The NUS 1975 georeferenced raster labels Japanese Garden on the island west of the former K. Tebing Terjun area. The current representative point is derived from the vertices of eight OpenStreetMap ways named Japanese Garden and is cross-checked against that historical label and the current NParks plan. This supports an orientation anchor inside the named landscape, not a cadastral or heritage boundary.', ['nus1975', 'osmReference', 'nparksBrochure']),
      record('Heritage now includes new forms of participation', 'The 2024 release names NParks, JTC, four educational institutions and Friends of Jurong Lake Gardens in the co-creation of five Floral Garden plots. Cultural form and present partnerships are therefore separate but connected layers of the site’s history.', ['nparks2024Opening']),
      reading('Political ecology: a tradition is translated', 'A Japanese-inspired tropical garden is not simply imported intact. Plant selection, water management, visitor circulation and public events continually translate its identity into local conditions. Our interpretation is that authenticity can lie in accumulated local meaning, even when the landscape’s horticulture is intentionally curated. Design resemblance alone cannot establish cultural authority or consensus.'),
      reading('A garden can be contemplative and operational', 'New bridges, aquatic collections and sheltered spaces invite circulation and gathering as well as quiet viewing. The relevant spatial tension is between a contemplative image and multiple everyday activities. It should be investigated at actual routes and facilities, not represented by a guessed island-wide behaviour zone.'),
      gap('Use dated design plans and photographs to separate original structures, later replacements and 2024 additions. Interviews should include users, gardeners and partner institutions; current planting descriptions are not evidence of the 1973 species assemblage.')
    ], ['floral-community-plots', 'living-lab-governance']),
    'former-fish-ponds': profile([
      record('Place and earlier use', 'The National Heritage Board places fish and prawn ponds beside Jurong River on land later developed as Chinese Garden. Its account identifies a productive water landscape but gives no pond operators, precise boundaries or household locations. This map therefore treats the case as a historical area of inquiry.', ['nhbChinese']),
      record('From ponds to garden', 'Chinese Garden was built under JTC’s Jurong Industrial Estate plan; construction began in 1971 and the garden was completed in April 1975. The official history explicitly links visitor attraction and greenery with industrial development. It does not date the closure of an individual pond.', ['nhbChinese']),
      record('How the place is represented', 'NParks’ current brochure foregrounds garden attractions and scenic water, while NHB’s online history also names the earlier ponds. These are different emphases across two sources. Whether signs inside the garden discuss pond livelihoods requires an on-site inventory.', ['nparksBrochure', 'nhbChinese']),
      reading('Political ecology: a change in the value of water', 'The documented change invites a comparison between water used for food production and water staged for recreation and cultural scenery. The garden may have met its stated visitor-attraction purpose, but these sources do not measure whose livelihood changed or how. No claim about a specific displaced worker follows from the map.', ['nhbChinese']),
      gap('Compare cadastral records, dated aerial images, acquisition files and oral histories before locating particular ponds or evaluating their loss. On-site interpretation could show the documented land-use sequence and explain the remaining uncertainty rather than presenting an invented pond boundary.')
    ], ['chinese-garden', 'jurong-river-trace', 'industrial-estate']),
    'jurong-river-trace': dossier([
      record('Read the original map before drawing a line', 'NUS provides historical cartography and its digitisation metadata. For the 1963 sheet, it identifies military and Singapore survey contributors and the later georeferencing work. The service is a mediated historical document, not a modern river survey.', ['nus1963']),
      record('Cross-check a cartographic change with a dated account', 'The retrospective 2024 speech connects the river-mouth sluice works to lake formation in 1971. That supports a transformation narrative, but does not prove the exact channel position, water level or the date on which any individual map symbol was surveyed.', ['pmoOpening']),
      reading('Political ecology: changing control, not only changing shape', 'A river-to-lake story is also a change in water control and ways of relating to the shore. Our reading asks how a working and flowing landscape became a managed recreational setting. Cartography can locate some physical traces; it cannot recover ownership, access customs or livelihood experience by itself.'),
      reading('What the timeline can honestly show', 'Crossfading dated maps lets visitors compare documented states. It does not calculate a continuous historical surface. Before digitising a river centreline, inspect the legend, scale and registration, use independent control points, and preserve uncertainty where channel symbols are ambiguous. The earlier speculative line stays off the map.'),
      gap('A defensible historical river feature would need a reproducible digitising record and an error estimate. Oral testimony should be linked to its recording and spatial confidence, not treated as a surveyed coordinate.')
    ], ['jurong-lake', 'former-fish-ponds']),
    'industrial-estate': dossier([
      record('Employment and recreation were connected projects', 'NHB reports 181 factories and a workforce of 20,000 by 1969. Its account describes poor early living conditions and the provision of cinemas and free Sunday boating to encourage workers to settle locally. These are regional historical figures and measures, not statistics for the present garden.', ['nhbIndustrial']),
      record('Workers appear as people, not only a workforce total', 'NHB’s Industrious Pioneers account includes Halijah binte Sulaiman’s work polishing cutlery at WMF and a family’s experience establishing a local hair salon. These named accounts open an everyday social history of industrialisation; neither identifies employment inside today’s garden.', ['nhbPioneers']),
      reading('Political ecology: green space within development', 'Stokols analyses Jurong as part of a wider account of state-led landscape production, linking economic development and symbolic green landscapes. We use that regional framework to interpret the garden’s relationship with industry, not as a site-specific pollution study or proof of displacement at this map location.', ['academicStokols']),
      reading('The story that an “oasis” metaphor leaves unfinished', 'Describing the garden as relief from urban life can separate it rhetorically from the work that produced the region. A richer account would follow both benefits and burdens: worker amenities, land transformation and ordinary labour. The available evidence supports their historical connection, but not a quantified local environmental burden.'),
      gap('Pair archival land-use maps with oral histories and dated environmental records. Do not assign present pollution, industrial exposure or forced relocation to a precise site without direct evidence. This regional case remains source-only.')
    ], ['lone-tree-memory', 'jurong-lake-district-vision']),
    'freshwater-swamp': profile([
      record('Place, habitat and intended visitors', 'NParks says Alstonia Island was planted to reflect Jurong’s freshwater swamp ecology. It names Marsh Pulai, a tree adapted to constant flooding. Nearby Rasau Walk offers a 300-metre boardwalk through a restored freshwater swamp with more than 50 plant species. These descriptions establish design and access, not a count of actual users.', ['nparksSwamp', 'nparksRasau']),
      record('A designed reference to an earlier ecology', 'The present planted landscape belongs to the Lakeside Garden project. NParks describes it as a reflection or restoration of freshwater swamp habitat; that wording does not establish survival of the same plants, soils or hydrology from before industrialisation. The exact historical ecosystem at this point remains undocumented here.', ['nparksSwamp', 'nparksRasau']),
      record('How nature is promoted', 'NParks invites visitors to explore Jurong’s natural history at Alstonia Island and to encounter a restored swamp from Rasau Walk. The boardwalk makes ecological processes accessible, while selecting a safe route and a particular view. No visitor learning survey is cited by these attraction pages.', ['nparksSwamp', 'nparksRasau']),
      reading('Political ecology: testing ecological authenticity', 'Planting and flood management can support real ecological processes. To assess whether the created habitat functions as an ecosystem, the relevant evidence would include plant recruitment, flooding patterns and species interactions over time. A promotional species count or a living specimen cannot establish self-sustaining recovery. Management choices also decide which habitat qualities visitors see.', ['nparksSwamp', 'nparksRasau']),
      gap('Publish a dated planting plan, maintenance history, hydrology and repeated biodiversity observations alongside the visitor description. Compare them with a defined reference habitat before claiming ecological equivalence. An audit of signs would establish what the on-site interpretation currently explains or omits.')
    ], ['floating-wetlands', 'living-lab-governance']),
    'grasslands': dossier([
      record('Tall grasses are resources, not empty scenery', 'NParks describes seed-feeding and shelter for small birds, three bird hides and several planted grasses. Its page specifically distinguishes the dominant Chinese Fountain Grass from Lalang. That is a managed planting description; it should not be converted into a claim that every grass is native or that species diversity has increased.', ['nparksGrasslands']),
      reading('Political ecology: design a way of looking', 'The bird hide changes the relationship between visitor and habitat: it channels observation and aims to reduce disturbance. Our reading is that wildlife appreciation is produced through access infrastructure, sightlines and visitor conduct. A hide’s presence demonstrates provision for viewing, not successful protection or a representative record of bird use.'),
      reading('Maintenance is part of the ecosystem question', 'Whether tall vegetation persists depends on management choices as well as ecological processes. For this case, cutting schedules, replacement planting, seed resources and habitat connectivity are relevant research dimensions. We have not located records that establish those schedules or their ecological effects, and do not invent them.'),
      record('Industrial memory within the habitat', 'The same official page identifies the Lone Tree as recycled reinforcement bars from old park paths, inspired by industrial Jurong. A visitor encounters both a habitat resource and a manufactured memory object in this landscape.', ['nparksGrasslands']),
      gap('Repeated bird observations with dates, effort and season, paired with maintenance records, would test habitat function. Comparing hide viewpoints with interpretive signs could show how wildlife and industry are framed without assuming viewers all read them identically.')
    ], ['lone-tree-memory', 'freshwater-swamp']),
    'floating-wetlands': dossier([
      record('A named operator and two stated functions', 'NParks places the floating wetland in the north of the Gardens, identifies it as man-made and names PUB’s ABC Waters Programme. It describes water-quality support and wildlife habitat together with a visitor boardwalk. These are official functional claims, not measured removal rates.', ['nparksWetlands']),
      reading('Political ecology: hybrid infrastructure', 'The installation is best read as a hybrid of living plants, a constructed floating system and a managed reservoir. Its artificial origin does not disqualify habitat value. The analytical issue is how those functions are produced and maintained, and whether public interpretation makes their dependencies visible.'),
      reading('Do not conflate this wetland with Clusia Cove', 'Clusia Cove’s dedicated page describes sand-based cleansing cells, filtration, ultraviolet treatment and pumped recirculation. That separate system demonstrates why “plants clean water” is an incomplete general explanation. We cannot transfer its treatment sequence, operating regime or performance to the floating wetland without evidence.', ['nparksClusia']),
      gap('Verify the floating installation’s design drawings, planting inventory, servicing records and inlet/outlet monitoring. Distinguish a habitat observation from a treatment evaluation. The map point is an orientation location, not the area over which performance was measured.')
    ], ['jurong-lake', 'living-lab-governance']),
    'forest-ramble': dossier([
      record('Wildlife movements become a play vocabulary', 'The dedicated NParks page describes a 2.3-hectare playgarden, 13 adventure stations inspired by freshwater-swamp fauna and inclusive play elements. Its animals are design references, not counts of animals inhabiting the playground.', ['nparksForest']),
      reading('Political ecology: a designed childhood encounter', 'This case translates an ecosystem into bodily activities. Children meet “nature” through climbing, movement, materials and caregiver supervision. Our reading is that recreation can create environmental familiarity while also simplifying ecology into a playable script. The existence of animal-themed equipment does not demonstrate what children learn or how they understand actual wildlife.'),
      reading('The invisible companions of a play facility', 'Caregivers’ time, shade, nearby toilets, drinking water and accessible paths condition who can remain comfortably. Those connections belong in the Public Use analysis, but a nearby amenity point does not prove an accessible route or a functioning service. The current operating page also reminds us that maintenance limits when play is possible.', ['nparksForest']),
      gap('Observe participation and waiting times, audit continuous accessible routes and interview children and caregivers using appropriate consent. Separate intended inclusivity from demonstrated use; do not infer disability or household characteristics from photographs.')
    ], ['therapeutic-garden', 'access-network']),
    'therapeutic-garden': dossier([
      record('Care has specific spatial provisions', 'NParks describes separate adult and child sections, wheelchair access, sensory zones and raised planters. The design anticipates seniors with dementia and children with particular support needs. This establishes intended provision, not a diagnosis of any visitor or a measured therapeutic outcome.', ['nparksTherapeutic']),
      reading('Political ecology: who is anticipated by public nature?', 'The garden makes bodily difference an explicit design concern. Our interpretation is that care is not supplied by greenery alone: surfaces, sensory intensity, resting places, gardening heights and supportive people matter. An inclusive destination still depends on the route from transport to the entrance and on the time and support available to a household.'),
      record('Use research at its actual scale', 'Ng and colleagues studied a structured horticultural-therapy programme in a randomised trial with 59 older adults. That is contextual evidence about a programme, not a clinical evaluation of this Jurong Lake Gardens feature. A garden description cannot inherit a trial’s outcomes merely because both involve plants.', ['academicNg']),
      reading('Design intention versus achieved benefit', 'Being wheelchair-accessible is a documented feature; equal experience remains an empirical question. For example, a route audit and participant interviews might identify fatigue, wayfinding or sensory barriers. Those possibilities are proposed checks, not reported failures of this garden.'),
      gap('A local evaluation would require defined participants, consent, exposure duration and appropriate outcome measures. Keep individual health information out of public GIS records. Current evidence supports the care-oriented design, not a claim that visiting treats dementia, autism or depression.')
    ], ['forest-ramble', 'access-network']),
    'access-network': dossier([
      record('Access begins outside the garden', 'NParks’ getting-here material identifies MRT approaches, bus connections and carparks. The current services page also describes information counters and wheelchair rental. These are distinct pieces of an access chain; a station point cannot stand in for the whole route.', ['nparksGettingHere', 'nparksServices']),
      reading('Political ecology: proximity is not equal accessibility', 'A short geographic distance can involve heat, crossings, gradients, poor wayfinding or a need for assistance. Our interpretation is that public nature is accessed through time and bodily effort, not distance alone. A car-lite aspiration may encourage active travel while still requiring accommodations for different mobility needs; it is not evidence that any group is excluded.'),
      reading('What a defensible accessibility layer would measure', 'Build a connected path network with verified surfaces, slopes, crossings, entrances and service hours. Test routes from each transport approach to care, play and toilet facilities, rather than drawing an arbitrary radius around the park. The current OSM paths are reference geometry, not a completed wheelchair-routing model.', ['osmReference']),
      gap('Record measured route conditions and dates, and distinguish published walking estimates from field timings. Validate the service chain with users. Do not publish a demographic catchment, access score or travel-time surface without its model and inputs.')
    ], ['lakeside-garden', 'therapeutic-garden']),
    'management': dossier([
      record('Public use is governed through concrete distinctions', 'Current NParks guidelines address feeding, plant removal, dogs, litter, smoking and activities in shared spaces. They distinguish dismount zones and provide an exception for people with disabilities. These rules describe a management regime; the point on this map is not a legal boundary.', ['nparksVisitorGuidelines']),
      reading('Political ecology: publicness includes rules about staying', 'The shelter etiquette discourages occupying common shared spaces with picnic mats and directs picnicking toward lawns. This makes governance visible at the scale of a place to sit, not only at the gate. Our reading asks how sharing, comfort and ecological protection are balanced; the guideline does not prove that enforcement is arbitrary or unequal.', ['nparksVisitorGuidelines']),
      reading('Institutions overlap, so one boundary is misleading', 'Garden management, reservoir functions and regional planning are related but not identical responsibilities. An administrative map would need actual mandates and jurisdictional data. In this GIS, a governance anchor signals a documented process rather than claiming exclusive authority over an invented zone.'),
      gap('Audit dated signs and restricted-area maps; compare them with official guidance and interview staff and users. Enforcement frequency, appeals, contested uses and budgets remain undocumented here. Do not treat a webpage summary as a substitute for the applicable legal instrument.')
    ], ['visitor-governance', 'living-lab-governance', 'community-engagement']),
    'lone-tree-memory': profile([
      record('Place, material and public use', 'The Lone Tree stands in the Grasslands. NParks says the sculpture uses iron reinforcement bars salvaged from old park pathways and was inspired by Jurong’s industrial origins. It is a visitor landmark and a potential perch for raptors; the page does not report how often birds or visitors use it.', ['nparksGrasslands']),
      record('The industrial history behind the symbol', 'NHB documents industrial workers and everyday services in Jurong, giving human detail to the development period that the sculpture evokes. Those regional stories do not identify the sculpture’s makers, the original source of every bar or an individual worker connected to this site.', ['nhbIndustrial', 'nhbPioneers']),
      record('How it is promoted', 'The official Grasslands page presents the object as both an iconic photo landmark and a reminder of industrial Jurong, within a habitat for small birds. This pairing makes industry legible during a nature visit. It does not show whether visitors recognise the labour histories behind the symbol.', ['nparksGrasslands']),
      reading('Political ecology: whose history becomes visible?', 'A sculpture made from reused path material connects construction, landscape maintenance and industrial memory in one object. Its visual shorthand can open a wider history, but it cannot carry accounts of work, land change and environmental costs by itself. The question is what material history the public is invited to follow beyond the icon.', ['nparksGrasslands', 'nhbPioneers']),
      gap('Link the sculpture to dated fabrication records and consented worker or resident testimony, and audit nearby signs before claiming a specific omission. Repeated wildlife observations would test the proposed perch function. A single sighting would establish an encounter, not habitat success.')
    ], ['grasslands', 'industrial-estate']),
    'community-engagement': dossier([
      record('An engagement count with a specific scope', 'NParks’ September 2024 completion release reports over 14,000 suggestions collected between November 2016 and April 2017 for Gardens Central and East, incorporated where feasible. “Suggestions” is the unit: it is not 14,000 unique residents or 14,000 accepted design changes.', ['nparks2024Opening']),
      record('Agenda setting and consultation are different stages', 'The opening speech describes the earlier leadership suggestion to refresh the gardens and the announcement of their combination into a national garden. Consultation followed an already framed redevelopment project. These accounts document different stages of decision-making, not proof that participation had no effect.', ['pmoOpening']),
      reading('Political ecology: participation is institutionally filtered', 'Our analysis follows the path from an invitation to give feedback, to assessment, to a built decision. Feasibility can involve ecological, financial, technical and management considerations. The release does not publish the weighting or decision log, so we cannot say which consideration prevailed or whether particular groups were systematically disadvantaged.'),
      reading('Evidence of involvement is not evidence of shared authority', 'Large participation numbers support the existence of engagement, but cannot alone show representative inclusion or control over final choices. A stronger account would compare retained landmarks and new uses with actual proposal records, while distinguishing consultation from co-design, volunteering and formal decision power.'),
      gap('Seek anonymised submissions, participant denominators, outreach languages, decision criteria and accepted/rejected proposal logs. The mapped point is not a townhall site. No percentage of suggestions implemented or demographic representativeness is claimed.')
    ], ['floral-community-plots', 'management', 'jurong-lake-district-vision']),
    'floral-community-plots': profile([
      record('Place, purpose and participants', 'NParks describes Floral Garden near the southern entrance of Japanese Garden as a Japanese-inspired display and a practical learning platform. Its account names students and partner organisations involved in co-created planting plots. These are intended participants and documented partners, not a survey of all visitors.', ['nparksFloral', 'nparks2024Opening']),
      record('A new layer in an older garden', 'Japanese Garden opened in 1973; Floral Garden’s five community plots belong to the 2024 rejuvenation. NParks names JTC, four educational institutions and Friends of Jurong Lake Gardens in the plot project. This dates the partnership without projecting its design back to the original garden.', ['nhbJapanese', 'nparks2024Opening']),
      record('How the garden is promoted', 'The attraction page presents Japanese garden design as a setting for student learning and curated planting. The 2024 announcement promotes the five plots as community co-creation. Neither source measures who visits the plots or how much authority partners hold after opening.', ['nparksFloral', 'nparks2024Opening']),
      reading('Political ecology: participation has a structure', 'Five plots make participation visible, but this is a named partnership with selected institutions. Comparing it with leased Allotment Gardens and open consultation reveals different rights to design, cultivate and decide. The public sources document involvement; they do not demonstrate representative participation or long-term ecological outcomes.', ['nparks2024Opening', 'nparksAllotments']),
      gap('Publish plot plans, partner roles and maintenance responsibilities; interview contributors about decisions they could make. A visitor survey could test the learning aim. On-site signs could name both the 1973 garden history and the people behind the new plots.')
    ], ['community-engagement', 'japanese-garden', 'facilities-l18']),
    'living-lab-governance': dossier([
      record('Separate technical plans from operational evidence', 'The Smart Technology page describes centralised monitoring and control through an Integrated Management System, but retains future-tense wording. Its description alone cannot establish which components are commissioned, their current coverage, or their measured performance.', ['nparksSmart']),
      record('Funding and water technology meet at a named place', 'NParks’ Sustainability page describes the Japanese Garden’s pumped and filtered water system and identifies Micron’s S$1 million donation through the Garden City Fund. This is a documented funding relationship; it is not a full operating budget or evidence that the donor controls visitor access.', ['nparksWaterSystems']),
      reading('Political ecology: sustainability has an operational politics', 'A sensor, pump or certification can make environmental management visible and auditable. Our reading asks what is monitored, which goals receive investment, who maintains the systems and what information is available to the public. Those questions should not be replaced by unverified claims of surveillance or complete efficiency.'),
      reading('Certification is not every environmental outcome', 'Efficient buildings, materials and water systems address different resource flows. A certification or a promotional description is not a whole-life carbon account, a biodiversity trend or a treatment-performance dataset. The case therefore retains each claimed intervention at its documented scope instead of giving the entire garden a single sustainability score.'),
      gap('Seek commissioning dates, system specifications, energy/water series and maintenance expenditure. Sensor coordinates and individual worker records are not published here. Any impact calculation would need transparent baselines and boundaries.')
    ], ['management', 'jurong-lake', 'floral-community-plots']),
    'visitor-governance': dossier([
      record('A rule page is spatial evidence with limits', 'NParks publishes garden etiquette and links a no-cycling-zone map. Some guidance is attraction-specific and includes disability exceptions. The official source, rather than a hand-drawn polygon, is the basis for investigating where movement is regulated.', ['nparksVisitorGuidelines']),
      reading('Political ecology: acceptable nature use is defined', 'Observing an animal, feeding it and removing it are different relationships with wildlife; rules rank those relationships differently. Likewise, riding and walking can be treated differently along a route. Our interpretation is that a public garden is produced through these permissions as well as through planting. Regulation can protect ecology and shared use without guaranteeing equal experience.'),
      reading('Do not mistake a general rule for every local condition', 'NParks’ Lakeside index also advertises fishing at the Southern Promenade. The apparent tension with general no-fishing wording is a reason to check designated zones and current signs, not to announce a garden-wide ban or permission. The GIS does not invent the extent of an exception.', ['nparksLakeside', 'nparksVisitorGuidelines']),
      gap('A useful field audit would record signs, dates, locations, official zone maps and how guidance is communicated in different languages. Legal scope and enforcement outcomes require direct verification; no penalty, enforcement rate or contested case has been inferred.')
    ], ['management', 'access-network']),
    'jurong-lake-district-vision': dossier([
      record('The garden sits inside a larger planning sequence', 'URA identifies the 1991 decentralisation strategy and the 2008 blueprint combining commercial Jurong Gateway with leisure-oriented Lakeside in a 410-hectare district. The current page describes a car-lite future anchored by parks, waterways and transport. Future plans are not completed facilities.', ['uraJurongLakeDistrict']),
      reading('Political ecology: amenity and development value coexist', 'Our interpretation is that the garden supports everyday recreation while also helping make a regional centre desirable and legible. Stokols offers a wider framework for studying state-led green landscapes in economic development. His regional cases are not a causal estimate of house prices around this garden.', ['academicStokols']),
      reading('An honest critical account needs distributional evidence', 'Greening can be a public benefit and a development strategy at the same time. To claim a trade-off, the GIS would need evidence of who receives access, who bears costs and what actually changes. We do not label nearby housing as gentrified or claim displacement merely because a plan promotes an attractive district.'),
      gap('Link dated master plans, completed infrastructure and disaggregated access or housing data with explicit methods. Do not merge Jurong Lake District with Jurong Innovation District or substitute a symbolic anchor for the district’s official boundary.')
    ], ['industrial-estate', 'community-engagement', 'access-network'])
  };
  // Named facility cases use their own documented process, not a left-panel lens profile.
  cases['stoneboat'] = profile([
    record('Place and documented uses', 'Stoneboat (邀月舫) is a two-storey structure beside Chinese Garden’s Lotus Pond. NParks describes its traditional Peking-style design and modern adaptations, and states that it once housed a branch of the Registrar of Marriage. The present attraction page invites viewing and photography; it gives no dates or counts for the former registration service.', ['nparksStoneboat']),
    record('Three stages of a public landscape', 'NHB identifies fish and prawn ponds on land later developed as Chinese Garden, completed in April 1975 within JTC’s industrial-estate plan. That is a garden date, not a verified opening date for Stoneboat. Its marriage-registration period is undated in the available NParks page. In 2024 NParks named Stoneboat among familiar landmarks retained and refreshed during the gardens’ rejuvenation.', ['nhbChinese', 'nparksStoneboat', 'nparks2024Opening']),
    record('How it is promoted', 'The current NParks page emphasises lunar views, architecture and the Lotus Pond; the brochure invites visitors to enjoy the romance of this landmark. The same attraction page also mentions marriage registration. The balance between scenic promotion and administrative history on signs inside the garden has not been audited.', ['nparksStoneboat', 'nparksBrochure']),
    reading('Political ecology: who defines a landmark’s value?', 'A state-built garden landmark acquired an administrative role in people’s life events and now appears within a curated heritage landscape. These changes show how institutions assign use and meaning to a cultural setting beside an engineered lake. Retention in 2024 documents a conservation choice; it does not establish that all original materials or former uses survived.', ['nhbChinese', 'nparksStoneboat', 'nparksAnnualReport']),
    gap('Find Registrar of Marriage records, dated photographs and conservation plans to establish operating years and material changes. Interview former users only with consent. An on-site sign audit could test whether the registration history is visible and could inform a concise public timeline.')
  ], ['chinese-garden', 'former-fish-ponds', 'facilities-c12']);
  cases['grand-arch'] = dossier([
    record('An entrance whose role has changed', 'NParks identifies Grand Arch as a landmark since 1975 and now lists the Gardens Gallery, Plant Factory and Canopy in its area. The current page explains the inscription 乾坤清气. These are the agency’s interpretation and current uses, not evidence that the later facilities existed at the opening.', ['nparksGrandArch']),
    reading('Heritage is conserved and put to work', 'The arch frames circulation, memory and photography while the surrounding facilities connect heritage to education, horticulture and dining. Our reading treats conservation as an active choice about uses, rather than freezing a building in an original moment. Commercial activity does not automatically erase public heritage; its relationship to public access needs local evidence.'),
    reading('A material landmark is not the entire history', 'The inscription and architectural icon can carry cultural meaning while leaving pond livelihoods and industrial work outside this particular frame. That is an analytical comparison with the heritage record, not a finding that the Gallery omits them; its displays require a separate audit.', ['nhbChinese']),
    gap('Compare dated photographs, conservation plans and Gallery interpretation; distinguish original fabric from restoration or new uses. The plan-derived point is aligned to the named building reference but is not a cadastral survey.')
  ], ['chinese-garden', 'former-fish-ponds']);
  cases['bonsai'] = dossier([
    record('Cultivation is part of the heritage', 'The dedicated NParks page dates the Bonsai Garden’s horticultural history from 1992 and describes a Suzhou-style setting with miniature landscapes. That is a later layer inside a Chinese Garden opened in 1975; the two dates must not be conflated.', ['nparksBonsai']),
    reading('Living heritage needs continuing work', 'Bonsai make the labour of shaping living plants especially visible. Our interpretation is that cultural authenticity is enacted through cultivation and display, not just inherited architecture. The miniature landscape is an artistic construction; it should not be read as a surviving local ecosystem or a conservation population without evidence.'),
    reading('A visitor account documents an encounter', 'The TravelFeed photo essay supplies an individual visitor’s account of this place. It can complement institutional imagery but cannot establish typical visitor experience, ecological success or the age of a photographed tree. Publication date and photo capture date remain different evidence.', ['socialTravelFeed']),
    gap('Seek collection records, plant provenance, horticultural practice and interviews with staff. Display the stated date of photographs and do not attribute an unverified origin or age to individual specimens.')
  ], ['chinese-garden']);
  cases['rasau'] = dossier([
    record('A route through a restored habitat', 'NParks describes the 300-metre boardwalk passing Nibong, Sealing Wax Palm and Rasau, with more than 50 plant species and feeding opportunities for shore birds. These are documented descriptions, not our own plant or bird survey.', ['nparksRasau']),
    reading('An ecotone is encountered through infrastructure', 'The boardwalk makes the land–water interface accessible while directing footsteps. Our reading is that visitor access and habitat are co-produced here: the route changes how people see and enter the edge. It is not evidence that disturbance is absent or that the restored community equals a historical swamp.'),
    gap('Audit the route’s surfaces, resting points and barriers; pair repeated observations with planting and hydrological records. The point is an entry to this case, not a digitised boardwalk alignment or an ecological sample area.')
  ], ['freshwater-swamp', 'access-network']);
  cases['clusia'] = profile([
    record('Place, facilities and intended users', 'Clusia Cove combines a water playground, cleansing biotope and eco-pond in Lakeside Garden. NParks describes a three-hectare play space where children encounter simulated tidal movement. Its current operating information identifies scheduled maintenance; it does not provide a visitor survey or past attendance.', ['nparksClusia']),
    record('How the water system was created', 'NParks describes a closed loop: water passes through sand and planted cleansing cells, Active Filter Media and ultraviolet treatment, returns to the play area, then moves through the eco-pond before recirculating. The attraction page explains the current arrangement but does not supply an as-built network or a dated commissioning record for each component.', ['nparksClusia']),
    record('How it is promoted', 'The official description presents water play as learning about tides and about “natural treatment”. Its technical explanation also names pumps, filter media and UV disinfection. Showing both makes the garden’s appeal and the labour of keeping play water usable part of the same account.', ['nparksClusia']),
    reading('Political ecology: an ecosystem with operating requirements', 'Living plants and microbes contribute to cleansing, while engineered filtration and servicing make public play possible. The system is a created landscape with real biological processes. Its purpose is stated clearly, but whether it consistently meets water-quality or educational goals needs dated monitoring and visitor evidence.', ['nparksClusia']),
    gap('Publish a simplified treatment diagram, monitoring dates and maintenance responsibilities near the playground. Obtain operational data before making performance claims. A visit or sign audit could show whether users understand the biological and mechanical parts of the cycle.')
  ], ['water-engineering', 'living-lab-governance', 'floating-wetlands']);
  cases['neram'] = dossier([
    record('A concrete drain was naturalised', 'NParks describes conversion of a drain from Yuan Ching Road into streams conveying runoff through planting toward Jurong Lake. It names a partnership with Temasek and connects the site with learning walks. This supports a specific transformation, not the restoration of a verified original river channel.', ['nparksNeram']),
    reading('Drainage, habitat and interpretation are linked', 'Our reading asks what is gained when drainage becomes visible as a habitat and learning route. The engineered function remains: runoff is still channelled. Natural-looking banks do not prove ecological equivalence to a wild stream, but a constructed stream can still sustain living interactions.'),
    gap('Use drainage plans, storm-event monitoring and before/after ecological observations to test cleansing and habitat claims. Do not apply a general waterway centreline to this feature unless its identity and alignment have been independently checked.')
  ], ['jurong-lake', 'freshwater-swamp']);
  cases['allotments'] = dossier([
    record('Participation has material and contractual conditions', 'NParks currently describes 300 raised-bed plots, each 2.5 by 1 metre, leased under its allotment scheme. This is organised cultivation with access conditions, not an open commons. Current lease terms need direct checking before application and should not be represented as historical 2024 prices.', ['nparksAllotments']),
    reading('Political ecology: who can cultivate public nature?', 'A plot gives participants a different relationship to plants from viewing a display. They can practise skills and produce food or ornament, but participation also requires time, knowledge and an allocated space. Those are plausible conditions to investigate, not proof of the actual class, age or income of plot holders.'),
    reading('Different kinds of community involvement', 'Compare leased cultivation here with partner-designed Floral Garden plots and the wider consultation exercise. The distinction is between sustained use rights, co-design and giving feedback; counting them all as “community participation” would obscure different degrees of agency.'),
    gap('Seek allocation rules, waiting lists, renewal practices and consented interviews. Plot count is capacity, not participation frequency, food output or a census of gardeners. No household productivity estimate has been inferred.')
  ], ['floral-community-plots', 'community-engagement']);
  cases['water-lily'] = dossier([
    record('A collection is not a wild species census', 'The dedicated NParks page promotes a collection of more than 150 water lily species and a panorama from the pavilion. This is a stated horticultural collection, not a count of locally native species or independent ecological sampling.', ['nparksLily']),
    record('The display depends on water management', 'NParks’ Sustainability page connects the Japanese Garden’s vegetation-and-microbe filtration with a pumped water system and a named donation. Living plants and engineered circulation jointly support the display.', ['nparksWaterSystems']),
    reading('Political ecology: ecological spectacle and operations', 'A large collection gives visitors an accessible way to encounter aquatic plants while making specialist cultivation less visible. Our analysis distinguishes horticultural richness, habitat function and resource demand. A visually diverse collection could be valuable without demonstrating native biodiversity recovery or self-sustaining ecological processes.'),
    gap('Verify collection records and taxonomic definitions, water/energy monitoring and maintenance practices. Never convert a collection total into a habitat-health score. The pavilion and garden are related but not interchangeable polygons.')
  ], ['japanese-garden', 'living-lab-governance']);
  cases['creek'] = dossier([
    record('An intentionally staged river landscape', 'NParks describes a designed habitat taking visitors through five river stages from highland streams to lowland swamps via a boardwalk. This is a condensed educational sequence, not proof that the original Jurong River had those stages at this location.', ['nparksCreek']),
    reading('Political ecology: make ecology legible', 'The sequence translates a large regional process into a visitor-scale encounter. Our reading values that teaching possibility while asking what is simplified: temporal flooding, sediment movement and ecological succession do not necessarily fit a fixed display. The distinction is between representing a process and empirically recreating its full dynamics.'),
    gap('Compare interpretation with design and operating records, and observe what visitors understand. Habitat names alone cannot establish connectivity, water source, ecological condition or correspondence with a historical channel.')
  ], ['jurong-river-trace', 'freshwater-swamp']);
  const aliases = {
    'Stoneboat': 'stoneboat',
    'Grand Arch': 'grand-arch', 'Canopy · Grand Arch': 'grand-arch',
    'Bonsai Garden': 'bonsai', 'BingXue · Bonsai Garden': 'bonsai',
    'Freshwater Swamp': 'freshwater-swamp', 'Alstonia Island': 'freshwater-swamp',
    'Grasslands': 'grasslands', 'Bird Hides': 'grasslands', 'The Lone Tree': 'lone-tree-memory',
    'Forest Ramble (Children’s Playground)': 'forest-ramble', 'Therapeutic Garden': 'therapeutic-garden',
    'Rasau Walk': 'rasau', 'Water Play at Clusia Cove': 'clusia', 'Clusia Cove Pavilion': 'clusia', 'Cleansing Biotope': 'clusia', 'Ecopond': 'clusia',
    'Neram Streams': 'neram', 'Allotment Gardens': 'allotments',
    'Water Lily Garden': 'water-lily', 'Water Lily Pavilion': 'water-lily',
    'Floral Garden': 'floral-community-plots', 'Cascading Creek': 'creek',
    'North Carpark': 'access-network', 'South Carpark': 'access-network', 'Lakeside MRT': 'access-network', 'Chinese Garden MRT': 'access-network', 'Jurong East MRT': 'access-network'
  };
  return { cases, aliases, newSources };
})();
